        const canvasOverlayCleanupPatch = `
  <script id="canvas-overlay-cleanup-patch">
    (function () {
      var selectors = [
        "volc-translate",
        "#agent",
        "#ai-assist-root-bangs",
        "#ai-assist-root-bilibili",
        "#ai-assist-root-new",
        "#ai-assist-bangs",
        "#shadow-root-ai-assist",
        "#immersive-translate-browser-popup",
        "#immersive-translate-popup-overlay",
        ".immersive-translate-popup-overlay",
        ".immersive-translate-popup-wrapper",
        ".imt-float-ball",
        ".imt-fb-side",
        ".imt-fb-container",
        ".qa-sdk-wrapper",
        "#youAsk_side",
        "[id^='youAsk']",
        "[class*='youAsk']",
        "[id*='ai-assist']",
        "[id*='immersive-translate']",
        "[class*='immersive-translate']"
      ].join(",");

      function removeOpenShadowHosts(root) {
        if (!root || root.nodeType !== 1) return;
        if (root.shadowRoot) {
          root.remove();
          return;
        }
        root.querySelectorAll("*").forEach(function (node) {
          if (node.shadowRoot) node.remove();
        });
      }

      function removeLargeForeignOverlayBranch(root) {
        if (!root || root.nodeType !== 1) return;
        // PRD: 清理脚本位于 head，首次执行时 body 可能尚未创建；此时直接等待后续 load/MutationObserver 清理，避免空 body 中断资产画布初始化。
        if ((root === document.documentElement || root === document.body) && !document.body) return;
        // PRD: HTML 解析期间 MutationObserver 会把画布内部新建的 Agent 面板、输入区等逐个交给清理函数；产品主体内的业务节点一律不走“大尺寸未知浮层”规则，防止初始化时误删引用条和输入组件。
        if (root !== document.documentElement && root !== document.body && root.closest("main.product")) return;
        // PRD: 首次清理只检查 body 直属浮层，运行期则只检查 MutationObserver 本次新增的宿主根；禁止递归扫描产品内部的 workspace、对话区等大尺寸绝对定位业务节点，否则会把资产节点画布主体误删并导致“从资产库选择/绑定音色”失效。
        var candidates = root === document.documentElement || root === document.body
          ? Array.from(document.body.children)
          : [root];
        candidates.forEach(function (node) {
          if (!node.isConnected || node === document.documentElement || node === document.body) return;
          // PRD: 画布合法的大尺寸定位层除页面框架外，还包含资产选择、绑定/更换音色、应用资产和下载确认弹窗；这些业务层必须保留可点击，扩展晚注入的未知半屏/全屏 fixed、absolute 宿主（含 closed Shadow DOM）才移除。
          // PRD: main.product 是画布全部节点与输入区的根容器，在主题覆盖下可能成为全屏定位层，必须作为产品主体保留，不能按未知大浮层删除。
          if (node.matches("main.product, .content-frame, .agent-localbar, .canvas-shell, .canvas-stage, #canvasSkillCreateModal, #canvasAssetImportOverlay, #characterVoiceModal, #characterVoiceLibrary, #assetApplyOverlay, #assetApplyContext, #nodeDownloadOverlay")) return;
          var style = getComputedStyle(node);
          if (style.position !== "fixed" && style.position !== "absolute") return;
          var rect = node.getBoundingClientRect();
          var coversLargeCanvasArea = rect.width >= window.innerWidth * .35 && rect.height >= window.innerHeight * .5;
          if (coversLargeCanvasArea) node.remove();
        });
      }

      function cleanupOverlayLayers() {
        document.querySelectorAll(selectors).forEach(function (node) {
          node.remove();
        });

        // PRD: 扩展样式即使脱离宿主也不能留在 iframe 中继续生成半屏蒙版；清理时必须结合 style 的 id，避免误删仅用于隐藏扩展宿主的业务主题。
        document.querySelectorAll("link[href^='chrome-extension://']").forEach(function (node) { node.remove(); });
        document.querySelectorAll("style").forEach(function (node) {
          var extensionPattern = /qa-sdk-wrapper|immersive-translate|youAsk_side|shadow-root-ai-assist|ai-assist-root/;
          // PRD: 带业务 id 的画布主题可能包含“隐藏扩展宿主”的选择器，不能因正文出现扩展关键词而误删；仅清理无 id 的扩展样式，或 id 本身就是扩展命名的样式。
          if (node.id && !extensionPattern.test(node.id)) return;
          if (extensionPattern.test((node.id || "") + " " + (node.textContent || ""))) node.remove();
        });

        // PRD: 画布业务不使用 Shadow DOM；无论扩展把宿主插在产品根内还是根外，只要含声明式模板或开放 shadowRoot 都直接移除，避免未知 ID 的顶层蒙版漏过名称白名单。
        document.querySelectorAll("template[shadowrootmode], template[shadowroot]").forEach(function (template) {
          var host = template.parentElement;
          if (host) host.remove();
        });

        // PRD: 扩展也可能把宿主追加成 html 的额外直接子节点；标准页面这里只允许 head/body，其余同层节点均为运行时注入层。
        Array.from(document.documentElement.children).forEach(function (node) {
          if (node === document.head || node === document.body) return;
          node.remove();
        });

        // PRD: 不再按 body 直属子节点白名单批量删除；资产选择、绑定/更换音色等弹窗均在运行期挂到 body。外部灰影只按扩展特征和大尺寸未知浮层识别，避免把正常业务弹窗删掉后造成按钮无响应。
      }

      cleanupOverlayLayers();
      removeOpenShadowHosts(document.documentElement);
      removeLargeForeignOverlayBranch(document.documentElement);
      // PRD: 父页面在 iframe load 后会再主动调用一次，覆盖浏览器扩展晚于 DOMContentLoaded 注入遮罩的时序。
      window.__vinaCleanupCanvasOverlays = function () {
        cleanupOverlayLayers();
        removeOpenShadowHosts(document.documentElement);
        removeLargeForeignOverlayBranch(document.documentElement);
      };
      new MutationObserver(function (records) {
        cleanupOverlayLayers();
        // PRD: 画布节点经常更新；后续只检查本次新增分支中的 Shadow DOM/大尺寸宿主，避免每次变化都全量遍历 iframe，同时拦住加载后再次注入的半屏灰色浮层。
        records.forEach(function (record) {
          record.addedNodes.forEach(function (node) {
            removeOpenShadowHosts(node);
            removeLargeForeignOverlayBranch(node);
          });
        });
      }).observe(document.documentElement, {
        childList: true,
        subtree: true
      });
    })();
  <\/script>`;
        const edgeCutHidePatch = `
  <script id="edge-cut-hide-patch">
    (function () {
      function isOverEdgeOrCutButton(target) {
        return !!(target && target.closest && (
          target.closest("[data-edge-hit]") ||
          target.closest(".edge-cut-button")
        ));
      }

      function hideStaleEdgeCutButton() {
        document.querySelectorAll(".edge.cut-hover").forEach(function (edge) {
          edge.classList.remove("cut-hover");
        });
        document.querySelector(".edge-cut-button.visible")?.classList.remove("visible");
      }

      document.addEventListener("pointermove", function (event) {
        if (isOverEdgeOrCutButton(event.target)) return;
        hideStaleEdgeCutButton();
      }, true);
    })();
  <\/script>`;
        const canvasConnectionRulesPatch = `
  <style id="canvas-connection-rules-style">
    /* PRD: 用户从节点连接点拉出连线时，当前起点节点上方标题区与下方信息区暂时隐藏；连线结束后随 connecting 状态移除自动恢复。 */
    .node.connecting .node-header,
    .node.connecting .node-footer,
    .node.connecting .character-asset-meta {
      opacity: 0 !important;
      visibility: hidden !important;
      pointer-events: none !important;
    }
  </style>
  <script id="canvas-connection-rules-script">
    (function () {
      var connectionRuleToastTimer = 0;

      function showConnectionRuleToast() {
        var toast = document.getElementById("connectionRuleToast");
        if (!toast) {
          toast = document.createElement("div");
          toast.id = "connectionRuleToast";
          toast.className = "canvas-title-toast";
          toast.setAttribute("role", "status");
          toast.setAttribute("aria-live", "polite");
          document.body.appendChild(toast);
        }
        toast.textContent = "视频节点不能连到图片节点上";
        toast.hidden = false;
        window.clearTimeout(connectionRuleToastTimer);
        connectionRuleToastTimer = window.setTimeout(function () { toast.hidden = true; }, 1800);
      }

      function mediaTypeOf(node) {
        if (!node) return "";
        if (typeof getNodeMediaType === "function") return getNodeMediaType(node) || "";
        if (node.querySelector(".thumb.video, .node-video")) return "video";
        if (node.querySelector(".thumb.image")) return "image";
        return node.dataset.nodeType || node.dataset.generationType || "";
      }

      function installConnectionDirectionRule() {
        if (typeof makeEdge !== "function" || makeEdge.__vinaDirectionRule) return;
        var originalMakeEdge = makeEdge;
        makeEdge = function (from, to, fromSide, toSide, record) {
          // PRD: 连线具有方向性——禁止视频节点作为起点连接到图片节点；拦截时在屏幕中央提示“视频节点不能连到图片节点上”。图片连接视频仍然允许。
          if (mediaTypeOf(from) === "video" && mediaTypeOf(to) === "image") {
            showConnectionRuleToast();
            return;
          }
          return originalMakeEdge(from, to, fromSide, toSide, record);
        };
        makeEdge.__vinaDirectionRule = true;
      }

      if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", installConnectionDirectionRule, { once: true });
      else installConnectionDirectionRule();
    })();
  <\/script>`;
