        const generationConfirmUiPatch = `
  <script id="generation-confirm-ui-patch">
    (function () {
      function patchCard(card) {
        var controls = card && card.querySelector("[data-generation-param-controls]");
        if (!controls || controls.dataset.splitParamReady === "true") return;
        var groups = Array.from(controls.querySelectorAll(":scope > .node-param-group"));
        if (groups.length < 2) return;

        var cardTitle = (card.querySelector(".generation-card-title")?.textContent || "").trim();
        if (cardTitle.includes("图片生成")) {
          var modelMenu = groups[0].querySelector(".model-menu");
          var modelLabel = groups[0].querySelector('[data-generation-param-label="model"]');
          if (modelMenu) {
            // 改动逻辑：AI 对话中的图片生成确认卡与画布节点共用新版图片模型名称，避免确认卡仍回退到旧的 MJ / Flux / SDXL 列表。
            modelMenu.innerHTML = ["Seedream 5.0 lite", "Gpt Image 2", "Nano Banana 2", "Nano Banana pro"].map(function (model, index) {
              return '<button class="node-param-option' + (index === 0 ? ' selected' : '') + '" type="button" data-generation-param-key="model" data-generation-param-value="' + model + '"><span><span>' + model + '</span></span>' + (index === 0 ? '<i data-lucide="check"></i>' : '') + '</button>';
            }).join("");
          }
          if (modelLabel) modelLabel.textContent = "Seedream 5.0 lite";
        }

        controls.dataset.splitParamReady = "true";
        controls.classList.remove("merged-param-control", "combined-open");
        controls.classList.add("split-param-control");

        var modelTrigger = groups[0].querySelector(".node-param-trigger");
        var settingsTrigger = groups[1].querySelector(".node-param-trigger");
        if (modelTrigger) modelTrigger.setAttribute("aria-label", "模型");
        if (settingsTrigger) settingsTrigger.setAttribute("aria-label", "其他参数");
      }

      function positionOpenMenu() {
        document.querySelectorAll(".generation-param-controls.split-param-control .node-param-group.open").forEach(function (group) {
          var trigger = group.querySelector(".node-param-trigger");
          var menu = group.querySelector(".node-param-menu");
          if (!trigger || !menu) return;
          var rect = trigger.getBoundingClientRect();
          var width = Math.min(340, Math.max(260, window.innerWidth - 28));
          var left = Math.min(Math.max(14, rect.left), Math.max(14, window.innerWidth - width - 14));
          var estimatedHeight = group.dataset.paramGroup === "model" ? 300 : 360;
          var below = rect.bottom + 8;
          var top = below + estimatedHeight <= window.innerHeight - 12
            ? below
            : Math.max(12, rect.top - Math.min(estimatedHeight, window.innerHeight - 24) - 8);
          menu.style.left = left + "px";
          menu.style.top = top + "px";
          menu.style.width = width + "px";
          menu.style.maxHeight = Math.max(180, window.innerHeight - top - 12) + "px";
        });
      }

      function patchAllCards() {
        document.querySelectorAll(".generation-card").forEach(patchCard);
      }

      document.addEventListener("click", function (event) {
        if (event.target.closest("[data-generation-param-menu]")) window.setTimeout(positionOpenMenu, 0);
      }, true);
      window.addEventListener("resize", positionOpenMenu);
      document.addEventListener("scroll", positionOpenMenu, true);

      var observer = new MutationObserver(patchAllCards);
      observer.observe(document.documentElement, { childList: true, subtree: true });
      if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", patchAllCards, { once: true });
      } else {
        patchAllCards();
      }
    })();
  <\/script>`;
