          entries.forEach(function(entry){clearTimeout(entry.startTimer);clearTimeout(entry.stopTimer);entry.media.pause();entry.media.removeAttribute('src');entry.media.load();entry.media.remove();if(entry.objectUrl)URL.revokeObjectURL(entry.objectUrl);});
