        document.addEventListener('pointerdown',function (event) { if(!event.target.closest('.libtv-export-wrap'))setExportMenuOpen(false); },true);
        /* 2026-08-07 改动逻辑：时间尺只负责移动播放头，不再作为“拖上去新增视频轨”的放置区域。 */
        var ruler=editor.querySelector('.libtv-ruler');
