        upload.setAttribute("aria-expanded", "false");
        upload.title = "添加素材";
        upload.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg>';

        var addMenu = document.createElement("div");
        addMenu.className = "canvas-chat-add-menu";
        addMenu.id = "canvasChatAddMenu";
        addMenu.hidden = true;
        addMenu.setAttribute("role", "menu");
        addMenu.innerHTML = '<button class="canvas-chat-add-option" type="button" role="menuitem" data-chat-add-local><i data-lucide="upload"></i><span>本地上传</span></button>' +
          '<button class="canvas-chat-add-option" type="button" role="menuitem" data-chat-add-library><i data-lucide="folder-open"></i><span>从资产库选择</span></button>';
        document.body.appendChild(addMenu);

        var strip = document.createElement("div");
        strip.className = "canvas-chat-image-strip";
        strip.id = "canvasChatImageStrip";
        strip.setAttribute("aria-label", "已添加图片");
