        const canvasAssetSaveUiPatch = `
  <style id="canvas-asset-save-ui-patch">
    #saveAssetModal .save-new-folder,
    #saveAssetModal .save-asset-tabs {
      display: none !important;
    }

    .canvas-asset-save-toast {
      position: fixed;
      left: 50%;
      top: 50%;
      z-index: 20000;
      transform: translate(-50%, -50%);
      padding: 12px 18px;
      border: 1px solid rgba(255, 255, 255, .14);
      border-radius: 10px;
      background: rgba(30, 30, 31, .96);
      color: #fff;
      box-shadow: 0 18px 50px rgba(0, 0, 0, .42);
      font-size: 14px;
      font-weight: 760;
      line-height: 1;
      pointer-events: none;
    }

    .canvas-asset-save-toast[hidden] {
      display: none;
    }
  </style>
  <script id="canvas-asset-save-ui-script">
    (function () {
      var toastTimer = 0;

      function syncAssetSaveModalCopy() {
        var modal = document.getElementById("saveAssetModal");
        if (!modal) return;
        var walker = document.createTreeWalker(modal, NodeFilter.SHOW_TEXT);
        var textNode;
        // 2026-08-17 Product Design 改动逻辑：只在原生保存分类弹窗内把标题“保存到素材库”统一为“保存到资产库”，分类与确认保存逻辑保持不变。
        while ((textNode = walker.nextNode())) textNode.nodeValue = textNode.nodeValue.replace(/保存到素材库/g, "保存到资产库");
      }

      window.showAssetSaveToast = function () {
        var toast = document.getElementById("canvasAssetSaveToast");
        if (!toast) {
          toast = document.createElement("div");
          toast.id = "canvasAssetSaveToast";
          toast.className = "canvas-asset-save-toast";
          toast.textContent = "已成功保存到资产库";
          toast.hidden = true;
          document.body.appendChild(toast);
        }
        toast.hidden = false;
        window.clearTimeout(toastTimer);
        toastTimer = window.setTimeout(function () { toast.hidden = true; }, 1800);
      };

      function syncSaveButton() {
        var button = document.getElementById("saveNodeAssetBtn");
        if (!button) return;
        var selected = document.querySelector(".node.selected");
        var type = selected && (selected.dataset.nodeType || selected.dataset.generationType || "");
        if (!type && selected) {
          var text = (selected.querySelector(".node-type")?.textContent || "").toLowerCase();
          if (/video|视频/.test(text)) type = "video";
          else if (/music|audio|音乐|音频/.test(text)) type = "music";
          else type = "image";
        }
        button.hidden = type === "video";
        button.style.display = type === "video" ? "none" : "";
      }

      document.addEventListener("pointerdown", function () { window.setTimeout(syncSaveButton, 0); }, true);
      new MutationObserver(function () {
        syncSaveButton();
        syncAssetSaveModalCopy();
      }).observe(document.documentElement, { childList: true, subtree: true, attributes: true, attributeFilter: ["class"] });
      function syncAssetSaveUi() { syncSaveButton(); syncAssetSaveModalCopy(); }
      if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", syncAssetSaveUi, { once: true });
      else syncAssetSaveUi();
    })();
  <\/script>`;
