        var chat = document.getElementById("chatPanel");
        var projectTitle = chat?.querySelector(".chat-project-title");
        var messagesNode = chat?.querySelector(".messages");
        var composerNode = chat?.querySelector(".composer-wrap");
        if (!chat || !projectTitle || chat.querySelector(".canvas-conversation-head")) return;

        var conversationHead = document.createElement("header");
        conversationHead.className = "canvas-conversation-head";
        conversationHead.setAttribute("aria-label", "对话 Agent 控制栏");
        // 2026-08-17 改动逻辑：展开态标题仅显示“Agent”，去掉“对话”二字，不改变收起、展开及消息交互逻辑。
