            '<button class="canvas-onboarding-action" type="button" data-canvas-onboarding-action="image-video" style="--guide-cover: url(&quot;' + dogHistoryImage + '&quot;);"><span class="canvas-onboarding-action-icon"><i data-lucide="video"></i></span><span class="canvas-onboarding-action-label">参考图生视频</span></button>' +
            '<button class="canvas-onboarding-action" type="button" data-canvas-onboarding-action="skills" style="--guide-cover: url(&quot;' + catHistoryImage + '&quot;);"><span class="canvas-onboarding-action-icon"><i data-lucide="blocks"></i></span><span class="canvas-onboarding-action-label">技能库</span></button>' +
          '</div>';
        workspaceNode.appendChild(guide);
