            addMessage("user", "生成一个猫的视频");
            var directionMessage = addMessage("ai", "可以，我给你三个方向，选一个就能继续生成：");
            directionMessage.insertAdjacentHTML("beforeend", '<div class="example-creative-choice-panel" aria-label="已回复的创意方向确认"><div class="example-creative-choice-title">创意方向确认</div><button class="creative-option example-disabled active" type="button" disabled aria-disabled="true"><span class="creative-option-index">1.</span><span class="example-creative-option-text"><span class="example-creative-option-title">阳光客厅小猫</span><span class="example-creative-option-subtitle">暖色自然光，小猫追逐毛线球，适合治愈生活感短视频。</span></span></button><button class="creative-option example-disabled" type="button" disabled aria-disabled="true"><span class="creative-option-index">2.</span><span class="example-creative-option-text"><span class="example-creative-option-title">赛博城市猫</span><span class="example-creative-option-subtitle">霓虹街头、雨夜反光，小猫穿过招牌和车灯，偏电影感。</span></span></button><button class="creative-option example-disabled" type="button" disabled aria-disabled="true"><span class="creative-option-index">3.</span><span class="example-creative-option-text"><span class="example-creative-option-title">童话森林猫</span><span class="example-creative-option-subtitle">小猫在发光蘑菇和花丛间探险，偏梦幻动画。</span></span></button><input class="creative-other-input example-disabled" type="text" placeholder="其他" disabled aria-disabled="true"></div>');
            addMessage("user", "选方向 A，阳光客厅小猫");
