        var deletedAgentMessageSnapshots = new Map();

        // 2026-08-14 改动逻辑：参考预览挂载到 body，确保悬停浮层能跨出结果卡片显示；媒体内容仍取自真实来源节点。
        var referencePreview = document.createElement("div");
