          var box = document.createElement("div");
          box.className = "local-redraw-region" + (selected ? " is-selected" : "");
          box.dataset.localRegionId = String(region.id);
          box.style.left = region.x + "%";
          box.style.top = region.y + "%";
          box.style.width = region.w + "%";
          box.style.height = region.h + "%";
          var label = document.createElement("span");
          label.className = "local-redraw-region-label";
          label.textContent = String(region.id);
          box.appendChild(label);
