        clone.querySelectorAll(".local-redraw-overlay").forEach(function (item) { item.remove(); });
        clone.querySelectorAll("[id]").forEach(function (item) { item.removeAttribute("id"); });
        // 2026-08-18 修复逻辑：从已有局部重绘节点继续派生时清除只对原 DOM 有效的绑定标记，让新克隆节点重新安装单击激活事件。
        delete clone.dataset.localRedrawActivationBound;
        delete clone.dataset.localRedrawGenerated;
        delete clone.dataset.vinaAttachmentNode;
        delete clone.dataset.sourceAttachmentId;
        delete clone.dataset.generationPrompt;
        delete clone.dataset.videoPlaybackBound;
