        clone.dataset.nodeOrigin = "local-redraw";
        clone.dataset.localRedrawNode = "true";
        clone.dataset.localRedrawSource = source.id;
        clone.dataset.localRedrawRegions = "[]";
        clone.dataset.localRedrawEditing = options.activate ? "true" : "false";
        clone.dataset.nodePromptDraft = "";
        clone.dataset.assetPrompt = "";
