    function setEpisodeCountPopoverOpen(open) {
      if (!episodeCountControl || !episodeCountPopover || !episodeCountToggle) return;
      episodeCountControl.classList.toggle("open", open);
      episodeCountPopover.hidden = !open;
      episodeCountToggle.setAttribute("aria-expanded", String(open));
    }

    function applyEpisodeCount(value) {
      const nextValue = Number.parseInt(value, 10);
      if (!Number.isFinite(nextValue) || nextValue < 1) return false;
      selectedEpisodeCount = nextValue;
      if (episodeCountLabel) episodeCountLabel.textContent = `${nextValue} 集`;
      episodeCountOptions.forEach((option) => {
        const active = Number(option.dataset.episodeCount) === nextValue;
        option.classList.toggle("active", active);
        option.setAttribute("aria-selected", String(active));
      });
      if (episodeCountInput) episodeCountInput.value = "";
      setEpisodeCountPopoverOpen(false);
      return true;
    }

    function commitCustomEpisodeCount() {
      if (!episodeCountInput?.value.trim()) return false;
      return applyEpisodeCount(episodeCountInput.value);
    }

    function setHomeEpisodeCountPopoverOpen(open) {
      if (!homeEpisodeCountControl || !homeEpisodeCountPopover || !homeEpisodeCountToggle) return;
      homeEpisodeCountControl.classList.toggle("open", open);
      homeEpisodeCountPopover.hidden = !open;
      homeEpisodeCountToggle.setAttribute("aria-expanded", String(open));
    }

    function applyHomeEpisodeCount(value) {
      const nextValue = Number.parseInt(value, 10);
      if (!Number.isFinite(nextValue) || nextValue < 1) return false;
      selectedHomeEpisodeCount = nextValue;
      if (homeEpisodeCountLabel) homeEpisodeCountLabel.textContent = `${nextValue} 集`;
      homeEpisodeCountOptions.forEach((option) => {
        const active = Number(option.dataset.homeEpisodeCount) === nextValue;
        option.classList.toggle("active", active);
        option.setAttribute("aria-selected", String(active));
      });
      if (homeEpisodeCountInput) homeEpisodeCountInput.value = "";
      setHomeEpisodeCountPopoverOpen(false);
      return true;
    }

    function commitCustomHomeEpisodeCount() {
      if (!homeEpisodeCountInput?.value.trim()) return false;
      return applyHomeEpisodeCount(homeEpisodeCountInput.value);
    }

    function setRatioPopoverOpen(control, popover, toggle, open) {
      if (!control || !popover || !toggle) return;
      control.classList.toggle("open", open);
      popover.hidden = !open;
      toggle.setAttribute("aria-expanded", String(open));
    }

    function applyRatio(value, label, options, dataKey, control, popover, toggle) {
      if (!value) return;
      if (label) label.textContent = value;
      options.forEach((option) => {
        const active = option.dataset[dataKey] === value;
        option.classList.toggle("active", active);
        option.setAttribute("aria-selected", String(active));
      });
      setRatioPopoverOpen(control, popover, toggle, false);
    }

    // 2026-08-18 改动逻辑：模型名称、说明和排列顺序与画布视频节点保持一致，Seedance 2.5 位于默认首选位置。
    const dramaVideoModelCatalog = [
      { name: "Happyhorse 1.0", description: "画质出众，运动与镜头更自然" },
      { name: "Kling v3 Omni", description: "多模态生成编辑，创作更可控" },
      { name: "Seedance 2.5", description: "新一代最强视频模型" },
      { name: "Seedance 2.0", description: "旗舰视频模型，音画与运镜稳定出色" },
      { name: "Seedance 2.0 fast", description: "旗舰能力加速，出片更高效" },
      { name: "Seedance 2.0 mini", description: "轻量低成本，批量创作更省" }
    ];

    const dramaModelIconMarkup = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="6" width="14" height="12" rx="3"/><path d="m17 10 4-2v8l-4-2z"/></svg>';
    const dramaModelCheckMarkup = '<svg class="drama-model-check" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';

    function renderDramaModelOptions(control) {
      const popover = control?.querySelector("[data-drama-model-popover]");
      const selectedModel = control?.dataset.dramaModel || "Seedance 2.5";
      if (!popover) return;
      popover.innerHTML = dramaVideoModelCatalog.map((model) => {
        const active = model.name === selectedModel;
        return `<button class="drama-model-option${active ? " active" : ""}" type="button" role="option" data-drama-model-option="${escapeHtml(model.name)}" aria-selected="${active}"><span class="drama-model-icon">${dramaModelIconMarkup}</span><span class="drama-model-copy"><span class="drama-model-name">${escapeHtml(model.name)}</span><span class="drama-model-description">${escapeHtml(model.description)}</span></span>${dramaModelCheckMarkup}</button>`;
      }).join("");
    }

    function setDramaModelPopoverOpen(control, open) {
      if (!control) return;
      const toggle = control.querySelector("[data-drama-model-toggle]");
      const popover = control.querySelector("[data-drama-model-popover]");
      if (!toggle || !popover) return;
      // 2026-08-18 Product Design 改动逻辑：首页继续按输入框底边计算向下间距；剧本阶段不再读取输入框顶部，弹层由 CSS 直接固定在模型按钮上方 14px。
      if (open) {
        const inputShell = control.closest(".ai-script-box, .script-input");
        const shellRect = inputShell?.getBoundingClientRect();
        const toggleRect = toggle.getBoundingClientRect();
        const isScriptStage = control.dataset.dramaModelScope === "script";
        const clearOffset = !isScriptStage && shellRect
          ? Math.max(14, Math.ceil(shellRect.bottom - toggleRect.bottom + 12))
          : 14;
        control.style.setProperty("--drama-model-dropdown-offset", `${clearOffset}px`);
      }
      control.classList.toggle("open", open);
      popover.hidden = !open;
      toggle.setAttribute("aria-expanded", String(open));
    }

    function closeDramaModelPopovers(except = null) {
      dramaModelControls.forEach((control) => {
        if (control !== except) setDramaModelPopoverOpen(control, false);
      });
    }

    function applyDramaModel(control, modelName) {
      if (!control || !dramaVideoModelCatalog.some((model) => model.name === modelName)) return;
      control.dataset.dramaModel = modelName;
      const label = control.querySelector("[data-drama-model-label]");
      const toggle = control.querySelector("[data-drama-model-toggle]");
      if (label) label.textContent = modelName;
      if (toggle) toggle.setAttribute("aria-label", `当前模型：${modelName}`);
      renderDramaModelOptions(control);
      setDramaModelPopoverOpen(control, false);
    }

    function closeScriptInputPopovers(except = null) {
      if (except !== "style") setRatioPopoverOpen(scriptStyleControl, scriptStylePopover, scriptStyleToggle, false);
      if (except !== "ratio") setRatioPopoverOpen(scriptRatioControl, scriptRatioPopover, scriptRatioToggle, false);
      if (except !== "count") setRatioPopoverOpen(scriptCountControl, scriptCountPopover, scriptCountToggle, false);
    }

    function renderScriptStylePicker() {
      if (scriptStyleCategories) {
        scriptStyleCategories.innerHTML = styleCategoryCatalog.map((category) => `<button class="style-category${category.id === activeScriptStyleCategory ? " is-active" : ""}" type="button" role="tab" aria-selected="${category.id === activeScriptStyleCategory}" data-script-style-category="${escapeHtml(category.id)}">${escapeHtml(category.name)}</button>`).join("");
      }
      if (scriptStyleList) {
        const styles = activeScriptStyleCategory === "all" ? styleCatalog : styleCatalog.filter((style) => style.category === activeScriptStyleCategory);
        scriptStyleList.innerHTML = styles.map((style) => `<button class="style-option${style.id === selectedScriptStyleId ? " is-selected" : ""}" type="button" role="option" aria-selected="${style.id === selectedScriptStyleId}" data-script-style-id="${escapeHtml(style.id)}"><span class="style-cover" style="--style-cover: ${escapeHtml(style.cover)};" aria-hidden="true"></span><span class="style-name">${escapeHtml(style.name)}</span></button>`).join("");
      }
    }

