      if (scriptArtStyleList) scriptArtStyleList.innerHTML = "<li>基础画风风格词：近未来校园、日漫写实、科幻悬疑。</li><li>视觉风格描述：白天使用清透自然光保留青春气息，夜间以冷青色走廊、紫色脉冲与老旧实验设备制造不安；关键线索采用克制特写和玻璃反射呈现。</li>";
      if (scriptSubjectGrid) scriptSubjectGrid.innerHTML = renderCardGrid([["林宇", "低调的转学生，能够吸收并反射异常能量，是星辉计划最后一名观察对象。"], ["张曼", "冷静敏锐的同桌，母亲与十七年前的实验事故有关。"], ["风衣男", "潜伏在校园中的旧实验幸存者，立场神秘却掌握核心证据。"], ["校长", "温和克制的学校管理者，实际负责维持星辉计划的运行。"]], "subject-card");
      if (scriptSceneGrid) scriptSceneGrid.innerHTML = renderCardGrid([["星辉高中", "明亮校园与隐秘监控系统共存的主要故事空间。"], ["旧实验楼", "被封锁的建筑，保存十七年前实验与记忆重置装置。"], ["校史馆", "光鲜历史陈列之下藏着被裁剪的照片与缺失档案。"], ["能力测评馆", "后期冲突集中发生的封闭场馆，能放大学生异能。"]], "scene-card");
      syncScriptPropSectionState(0);
