    seedEpisodeShots();
    installShotScrollbar();
    refreshShotCards().forEach((card) => {
      ensureShotControls(card);
      syncShotCardVisualState(card);
    });
    defaultEpisodeShotGenerationStates = Array.from(refreshShotCards(), (card) => getShotGenerationState(card));
    persistCurrentEpisodeShotState(currentEpisodeVideoTitle);
    refreshEpisodeListStates();
    syncShotIndexes();

    shotStrip?.addEventListener("click", (event) => {
      const addButton = event.target.closest(".shot-add-btn");
      const deleteButton = event.target.closest(".shot-delete-btn");
      const failureConfirm = event.target.closest(".shot-failure-confirm");
      const card = event.target.closest(".shot-card");
      if (!card) return;

      // 2026-07-24 改动逻辑：失败卡确认按钮不触发片段播放/选中副作用，直接复用右侧失败预览的恢复逻辑。
      if (failureConfirm) {
        event.preventDefault();
        event.stopPropagation();
        confirmShotGenerationFailure(card);
        return;
      }

      if (addButton) {
        event.preventDefault();
        event.stopPropagation();
        insertShotBeside(card, addButton.dataset.insertSide || "right");
        return;
      }

      if (deleteButton) {
        event.preventDefault();
        event.stopPropagation();
        pendingShotDelete = card;
        lastProjectDeleteButton = deleteButton;
        document.getElementById("projectDeleteTitle").textContent = "删除片段";
        document.getElementById("projectDeleteMessage").textContent = "确认要删除该片段吗？";
        projectDeleteModal.hidden = false;
        projectDeleteCancel.focus();
        return;
      }

      setActiveShot(card, true);
    });

    shotStrip?.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      const action = event.target.closest(".shot-add-btn, .shot-delete-btn, .shot-failure-confirm");
      if (!action) return;
      event.preventDefault();
      action.click();
    });

    // 2026-07-24 改动逻辑：底部失败卡和右侧失败预览共用一个确认函数；两处确认都会恢复 pending、同步当前预览并保存本集状态。
    function confirmShotGenerationFailure(card) {
      if (!card || getShotGenerationState(card) !== "failed") return;
      card.dataset.generationState = "pending";
      syncShotCardVisualState(card);
      persistCurrentEpisodeShotState();
      if (card === getActiveShotCard()) setActiveShot(card, false);
    }

    // 改动逻辑：短剧失败预览的确认按钮在只读示例中仍属于浏览/清除提示交互；按下时阻断外层播放器事件。
    ["pointerdown", "mousedown"].forEach((eventName) => {
      detailPreview?.addEventListener(eventName, (event) => {
        if (!event.target.closest(".detail-generation-failure-confirm")) return;
        event.stopPropagation();
      });
    });
    detailPreview?.addEventListener("click", (event) => {
      const confirmButton = event.target.closest(".detail-generation-failure-confirm");
      if (!confirmButton) return;
      event.preventDefault();
      event.stopPropagation();
      const activeCard = getActiveShotCard();
      confirmShotGenerationFailure(activeCard);
    });

	    // PRD: 删除分集片段引用素材时，输入框内引用同一素材的所有 @ 标签也必须同步删除，避免生成提示词继续携带已失效的图片或音频引用。
	    function removeDetailMentionsForReference(card) {
	      if (!detailPromptText || !card) return;
	      const referenceName = card.querySelector(".detail-reference-name")?.textContent?.trim() || "";
	      const referenceLabel = card.dataset.referenceLabel || "";
	      detailPromptText.querySelectorAll(".detail-mention-token").forEach((token) => {
	        const tokenName = token.dataset.referenceMention?.trim() || "";
	        const tokenLabel = token.textContent.replace(/^@/, "").trim();
	        if ((referenceName && tokenName === referenceName) || (referenceLabel && tokenLabel === referenceLabel)) token.remove();
	      });
	      // PRD: 主动派发 input 事件，让当前片段卡片的数据和历史记录逻辑接收到删除后的最新提示词。
	      detailPromptText.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "deleteContent" }));
	    }

	    detailReferenceList?.addEventListener("click", (event) => {
	      const removeButton = event.target.closest(".detail-reference-remove");
	      if (removeButton) {
	        const referenceCard = removeButton.closest(".detail-reference-card");
	        removeDetailMentionsForReference(referenceCard);
	        referenceCard?.remove();
	        syncDetailReferenceLabels();
	        hideReferenceMentionPopover();
	        return;
	      }
	      const card = event.target.closest(".detail-reference-card");
	      if (!card) return;
	      openReferencePreview(getReferencePreviewAssetFromCard(card));
	    });

    const referenceEpisodeAssets = [
      { name: "林宇-基础形象", kind: "role" },
      { name: "音色：林宇", kind: "audio", roleName: "林宇" },
      { name: "林宇-校服形象", kind: "uniform" },
      { name: "校长", kind: "headmaster" },
      { name: "音色：校长", kind: "audio", roleName: "校长" },
      { name: "星辉高中教室", kind: "scene" },
      { name: "旧实验楼走廊", kind: "corridor" }
    ];
    const referenceAllAssets = referenceEpisodeAssets.concat([
      { name: "林宇-成年形象", kind: "role" },
      { name: "张曼-基础形象", kind: "uniform" },
      { name: "王老师", kind: "headmaster" },
      { name: "校史馆", kind: "scene" },
      { name: "地下设备间", kind: "corridor" }
    ]);
    const referenceLibraryAssets = {
      character: [
        { name: "清冷师妹", kind: "role", bg: "#89857a", skin: "#f0c9b9", outfit: "#e9d9ef" },
        { name: "乖巧男孩", kind: "uniform", bg: "#f1f1f1", skin: "#e7c1a7", outfit: "#eadbc6" },
        { name: "天真少女", kind: "role", bg: "#7f8588", skin: "#dfb595", outfit: "#99bfd8" },
        { name: "文雅学生", kind: "uniform", bg: "#777", skin: "#ddb092", outfit: "#1e2838" },
        { name: "端庄太太", kind: "headmaster", bg: "#85837f", skin: "#e3b79c", outfit: "#3c8c68" },
        { name: "卖报少年", kind: "role", bg: "#8b8175", skin: "#d9aa80", outfit: "#caa676" },
        { name: "凌厉刺客", kind: "headmaster", bg: "#747474", skin: "#d0a07d", outfit: "#191b1e" },
        { name: "学院新生", kind: "uniform", bg: "#8393a2", skin: "#e1b28f", outfit: "#2870bd" },
        { name: "神秘来客", kind: "role", bg: "#777", skin: "#d8aa84", outfit: "#263241" },
        { name: "沉稳长者", kind: "headmaster", bg: "#8a8178", skin: "#c99670", outfit: "#34302e" }
      ],
      scene: [
        { name: "清晨教室", kind: "scene", sceneBg: "linear-gradient(180deg,#86b3d6 0 45%,#354b61 46% 67%,#171f2c 68% 100%)" },
        { name: "旧实验楼", kind: "corridor", sceneBg: "radial-gradient(circle at 72% 28%,rgba(174,72,137,.55),transparent 28%),linear-gradient(145deg,#111826,#26364b 48%,#080b10 100%)" },
        { name: "校史馆展厅", kind: "scene", sceneBg: "linear-gradient(150deg,#756a58,#b89c70 48%,#211d18 100%)" },
        { name: "地下设备间", kind: "corridor", sceneBg: "linear-gradient(145deg,#10151c,#334354 52%,#050709 100%)" },
        { name: "雨夜走廊", kind: "scene", sceneBg: "radial-gradient(circle at 64% 20%,rgba(91,126,197,.5),transparent 24%),linear-gradient(160deg,#111827,#26364b 56%,#080b10 100%)" }
      ],
      prop: [],
      voice: [
        { name: "清朗少年", kind: "audio", roleName: "林宇" },
        { name: "威严长者", kind: "audio", roleName: "校长" },
        { name: "温柔学长", kind: "audio", roleName: "林宇" },
        { name: "坚定女主", kind: "audio", roleName: "张曼" }
      ]
    };
    let selectedReferenceLibraryAsset = null;
    let activeReferenceSource = "episode";
    let activeReferenceCategory = "character";
    let referenceInsertMode = "reference";
	    let referenceMentionRange = null;
	    let referenceMentionTriggerNode = null;
	    let referenceMentionTriggerPending = false;
	    let referenceAudioCount = 0;
	    let referenceAudioPreviewTimer = null;
	    let referenceAudioPreviewStart = 0;
	    let referenceAudioPreviewElapsed = 0;
	    const referenceAudioPreviewDuration = 3;

	    function referenceKindClass(kind) {
	      return kind === "audio" ? "audio-ref" : kind === "style" ? "style-ref" : kind === "uniform" ? "uniform" : kind === "headmaster" ? "headmaster" : kind === "scene" ? "scene" : kind === "corridor" ? "corridor" : "role";
	    }

	    function formatReferenceAudioTime(seconds) {
	      const safeSeconds = Math.max(0, Math.min(referenceAudioPreviewDuration, seconds || 0));
	      return `0:${String(Math.floor(safeSeconds)).padStart(2, "0")} / 0:${String(referenceAudioPreviewDuration).padStart(2, "0")}`;
	    }

	    function setReferenceAudioPreviewPlaying(isPlaying) {
	      referenceAudioPreviewPlay?.setAttribute("aria-label", isPlaying ? "暂停音频" : "播放音频");
	      if (referenceAudioPreviewIcon) referenceAudioPreviewIcon.innerHTML = isPlaying ? '<path d="M7 5h4v14H7zM13 5h4v14h-4z"/>' : '<path d="M8 5v14l11-7z"/>';
	    }

	    function updateReferenceAudioPreviewProgress(seconds) {
	      referenceAudioPreviewElapsed = Math.max(0, Math.min(referenceAudioPreviewDuration, seconds || 0));
	      if (referenceAudioPreviewTime) referenceAudioPreviewTime.textContent = formatReferenceAudioTime(referenceAudioPreviewElapsed);
	      referenceAudioPreviewTrack?.style.setProperty("--audio-preview-progress", `${(referenceAudioPreviewElapsed / referenceAudioPreviewDuration) * 100}%`);
	    }

	    function stopReferenceAudioPreview() {
	      if (referenceAudioPreviewTimer) window.clearInterval(referenceAudioPreviewTimer);
	      referenceAudioPreviewTimer = null;
	      setReferenceAudioPreviewPlaying(false);
	    }

	    function toggleReferenceAudioPreviewPlayback() {
	      if (referenceAudioPreviewTimer) {
	        stopReferenceAudioPreview();
	        return;
	      }
	      setReferenceAudioPreviewPlaying(true);
	      referenceAudioPreviewStart = Date.now() - referenceAudioPreviewElapsed * 1000;
	      referenceAudioPreviewTimer = window.setInterval(() => {
	        const elapsed = (Date.now() - referenceAudioPreviewStart) / 1000;
	        updateReferenceAudioPreviewProgress(elapsed);
	        if (elapsed >= referenceAudioPreviewDuration) {
	          stopReferenceAudioPreview();
	          updateReferenceAudioPreviewProgress(0);
	        }
	      }, 80);
	    }

	    function closeReferencePreview() {
	      stopReferenceAudioPreview();
	      referenceImagePreviewOverlay && (referenceImagePreviewOverlay.hidden = true);
	      referenceAudioPreviewOverlay && (referenceAudioPreviewOverlay.hidden = true);
	    }

	    function getReferencePreviewAssetFromCard(card) {
	      if (!card) return null;
	      const name = card.querySelector(".detail-reference-name")?.textContent?.trim() || card.dataset.referenceLabel || "参考资产";
	      const kind = card.classList.contains("audio-ref") ? "audio" : card.classList.contains("style-ref") ? "style" : card.classList.contains("uniform") ? "uniform" : card.classList.contains("headmaster") ? "headmaster" : card.classList.contains("scene") ? "scene" : card.classList.contains("corridor") ? "corridor" : "role";
	      const cover = getComputedStyle(card).backgroundImage;
	      return { name, label: card.dataset.referenceLabel || name, kind, cover: cover && cover !== "none" ? cover : "" };
	    }

	    function getReferencePreviewAssetFromMention(token) {
	      if (!token) return null;
	      const name = token.dataset.referenceMention || token.textContent.replace(/^@/, "").trim() || "参考资产";
	      const thumb = token.querySelector(".detail-mention-thumb");
	      const kind = thumb?.classList.contains("audio-ref") ? "audio" : thumb?.classList.contains("style-ref") ? "style" : thumb?.classList.contains("uniform") ? "uniform" : thumb?.classList.contains("headmaster") ? "headmaster" : thumb?.classList.contains("scene") ? "scene" : thumb?.classList.contains("corridor") ? "corridor" : "role";
	      const cover = thumb ? getComputedStyle(thumb).backgroundImage : "";
	      return { name, label: token.textContent.replace(/^@/, "").trim() || name, kind, cover: cover && cover !== "none" ? cover : "" };
	    }

	    function openReferencePreview(asset) {
	      if (!asset) return;
	      closeReferencePreview();
	      // PRD: 图片弹窗顶部显示与 hover 浮层一致的素材名；音频弹窗只保留素材名、播放/暂停、时间和进度条。
	      if (asset.kind === "audio") {
	        if (referenceAudioPreviewTitle) referenceAudioPreviewTitle.textContent = asset.name;
	        updateReferenceAudioPreviewProgress(0);
	        if (referenceAudioPreviewOverlay) referenceAudioPreviewOverlay.hidden = false;
	        return;
	      }
	      if (referenceImagePreviewTitle) referenceImagePreviewTitle.textContent = asset.name;
	      if (referenceImagePreviewStage) referenceImagePreviewStage.style.setProperty("--reference-preview-cover", asset.cover || "linear-gradient(135deg,#202631,#101217)");
	      if (referenceImagePreviewOverlay) referenceImagePreviewOverlay.hidden = false;
	    }

	    function addReferenceAsset(asset) {
      if (!detailReferenceList || !detailReferenceAdd || !asset) return;
      const card = document.createElement("article");
      card.className = `detail-reference-card ${referenceKindClass(asset.kind)}`;
      if (asset.kind === "audio") card.dataset.audioRole = asset.roleName || getDetailReferenceAudioRoleName();
      card.innerHTML = `<span class="detail-reference-name">${escapeHtml(asset.name)}</span><button class="detail-reference-remove" type="button" aria-label="删除${escapeHtml(asset.name)}参考图">×</button>`;
      detailReferenceList.insertBefore(card, detailReferenceAdd);
      // PRD: 新加入的参考图如果是上一阶段已存在的角色资产，立即替换为资产画布中的对应图片。
      syncDetailReferenceAssetCovers();
      syncDetailReferenceLabels();
    }

    function insertReferenceMention(asset) {
      if (!detailPromptText || !asset) return;
      detailPromptText.focus();
      const selection = window.getSelection();
      const range = referenceMentionRange && detailPromptText.contains(referenceMentionRange.commonAncestorContainer) ? referenceMentionRange : document.createRange();
      if (!referenceMentionRange || !detailPromptText.contains(referenceMentionRange.commonAncestorContainer)) {
        range.selectNodeContents(detailPromptText);
        range.collapse(false);
      }
      const token = document.createElement("span");
      token.className = "detail-mention-token";
      token.contentEditable = "false";
      token.dataset.referenceMention = asset.name;
      const coverStyle = asset.cover ? ` style="background-image:${escapeHtml(asset.cover)}"` : "";
      token.innerHTML = `<span class="detail-mention-thumb ${referenceKindClass(asset.kind)}"${coverStyle}></span><span>@${escapeHtml(asset.label || asset.name)}</span>`;
      if (referenceMentionTriggerNode?.isConnected) {
        referenceMentionTriggerNode.replaceWith(token);
      } else {
        const triggerRange = range.cloneRange();
        if (triggerRange.startContainer?.nodeType === Node.TEXT_NODE && triggerRange.startOffset > 0 && triggerRange.startContainer.textContent.slice(triggerRange.startOffset - 1, triggerRange.startOffset) === "@") {
          triggerRange.setStart(triggerRange.startContainer, triggerRange.startOffset - 1);
          triggerRange.deleteContents();
          range.setStart(triggerRange.startContainer, triggerRange.startOffset);
          range.collapse(true);
        }
        range.insertNode(token);
      }
      const spacer = document.createTextNode("\u00a0");
      token.after(spacer);
      range.setStartAfter(spacer);
      range.collapse(true);
      selection.removeAllRanges();
      selection.addRange(range);
      referenceMentionRange = null;
      referenceMentionTriggerNode = null;
      hideReferenceMentionPopover();
    }

    function commitReferenceAsset(asset) {
      if (referenceInsertMode === "mention") insertReferenceMention(asset);
      else addReferenceAsset(asset);
    }

    function renderReferenceAssetBody(scope = "episode") {
      const assets = scope === "all" ? referenceAllAssets : referenceEpisodeAssets;
      const roles = assets.filter((asset) => !["scene", "corridor"].includes(asset.kind));
      const scenes = assets.filter((asset) => ["scene", "corridor"].includes(asset.kind));
      const section = (title, items) => `<section class="reference-asset-section"><h3 class="reference-asset-section-title">${title}</h3><div class="reference-asset-list">${items.map((asset) => `<button class="reference-asset-item" type="button" data-reference-name="${escapeHtml(asset.name)}" data-reference-kind="${asset.kind}" data-reference-role="${escapeHtml(asset.roleName || "")}"><span class="reference-asset-preview ${referenceKindClass(asset.kind)}"></span><span class="reference-asset-item-name">${escapeHtml(asset.name)}</span></button>`).join("")}</div></section>`;
      referenceAssetBody.innerHTML = section("角色", roles) + section("场景", scenes);
    }

    function referenceLibraryPreview(asset) {
      if (asset.kind === "audio") return `<div class="reference-library-audio" aria-hidden="true"></div>`;
      if (["scene", "corridor"].includes(asset.kind)) {
        return `<div class="reference-library-scene" style="--scene-bg:${escapeHtml(asset.sceneBg || "linear-gradient(180deg,#86b3d6 0 45%,#354b61 46% 67%,#171f2c 68% 100%)")}" aria-hidden="true"></div>`;
      }
      return `<div class="subject-portrait" style="--portrait-bg:${escapeHtml(asset.bg || "#777")};--skin:${escapeHtml(asset.skin || "#e8c4ac")};--outfit:${escapeHtml(asset.outfit || "#2d3440")};" aria-hidden="true"></div>`;
    }

    function referenceAssetsForSource(source, category) {
      const categoryMatches = (asset) => category === "voice" ? asset.kind === "audio" : category === "scene" ? ["scene", "corridor"].includes(asset.kind) : category === "prop" ? asset.kind === "prop" : !["audio", "scene", "corridor", "prop"].includes(asset.kind);
      if (source === "episode") return referenceEpisodeAssets.filter(categoryMatches);
      if (source === "all") return referenceAllAssets.filter(categoryMatches);
      if (source === "public") return referenceLibraryAssets[category] || [];
      return [];
    }

    function renderReferenceLibrary(category = activeReferenceCategory, source = activeReferenceSource) {
      // PRD 2026-07-08: 不同来源只切换数据，卡片 DOM 与单选逻辑完全共用，避免五个 Tab 出现不同视觉规格。
      activeReferenceCategory = category;
      activeReferenceSource = source;
      selectedReferenceLibraryAsset = null;
      if (confirmReferenceImport) confirmReferenceImport.disabled = true;
      const assets = referenceAssetsForSource(source, category);
      referenceLibraryGrid.innerHTML = assets.length ? assets.map((asset) => `<button class="reference-library-card" type="button" data-library-name="${escapeHtml(asset.name)}" data-library-kind="${asset.kind}" data-library-role="${escapeHtml(asset.roleName || "")}">${referenceLibraryPreview(asset)}<span class="reference-library-name">${escapeHtml(asset.name)}</span></button>`).join("") : `<div class="reference-library-empty">暂无${category === "character" ? "角色" : category === "scene" ? "场景" : category === "prop" ? "物品" : "音色"}资产</div>`;
    }

    function getDetailReferenceMentionAssets() {
      if (!detailReferenceList) return [];
      return Array.from(detailReferenceList.querySelectorAll(".detail-reference-card")).map((card) => {
        const name = card.querySelector(".detail-reference-name")?.textContent?.trim() || "";
        const label = card.dataset.referenceLabel || name;
        const kind = card.classList.contains("audio-ref") ? "audio" : card.classList.contains("style-ref") ? "style" : card.classList.contains("uniform") ? "uniform" : card.classList.contains("headmaster") ? "headmaster" : card.classList.contains("scene") ? "scene" : card.classList.contains("corridor") ? "corridor" : "role";
        const cover = getComputedStyle(card).backgroundImage;
        return { name, label, kind, cover: cover && cover !== "none" ? cover : "" };
      }).filter((asset) => asset.name);
    }

    function createDetailMentionToken(asset) {
      const token = document.createElement("span");
      token.className = "detail-mention-token";
      token.contentEditable = "false";
      token.dataset.referenceMention = asset.name;
      const thumb = document.createElement("span");
      thumb.className = `detail-mention-thumb ${referenceKindClass(asset.kind)}`;
      if (asset.cover) thumb.style.backgroundImage = asset.cover;
      const label = document.createElement("span");
      label.textContent = `@${asset.label || asset.name}`;
      token.append(thumb, label);
      return token;
    }

    function setDetailPromptContent(prompt) {
      if (!detailPromptText) return;
      const text = String(prompt || "");
      const assets = getDetailReferenceMentionAssets();
      const assetByLabel = new Map(assets.map((asset) => [asset.label.replace(/\s+/g, ""), asset]));
      const mentionPattern = /@(图片|音频)\s*(\d+)/g;
      let cursor = 0;
      let match;
      detailPromptText.replaceChildren();
      // PRD: 预置提示词里出现 @图片/@音频 时，按参考卡片编号自动渲染成可视化标签，而不是普通文本。
      while ((match = mentionPattern.exec(text))) {
        if (match.index > cursor) detailPromptText.append(document.createTextNode(text.slice(cursor, match.index)));
        const asset = assetByLabel.get(`${match[1]}${match[2]}`);
        if (asset) detailPromptText.append(createDetailMentionToken(asset));
        else detailPromptText.append(document.createTextNode(match[0]));
        cursor = match.index + match[0].length;
      }
      if (cursor < text.length) detailPromptText.append(document.createTextNode(text.slice(cursor)));
    }

    function positionReferenceMentionPopover(rect) {
      if (!detailMentionPopover) return;
      const fallback = detailPromptText?.getBoundingClientRect();
      const source = rect && (rect.width || rect.height) ? rect : fallback;
      if (!source) return;
      const width = 190;
      const height = detailMentionPopover.offsetHeight || 240;
      const left = Math.min(window.innerWidth - width - 12, Math.max(12, source.left));
      const belowTop = source.bottom + 4;
      const aboveTop = source.top - height - 4;
      // PRD: @ 弹窗默认贴在 @ 字符正下方；只有视口底部放不下时才上翻，避免被右侧视频或底部控制区遮挡。
      const top = belowTop + height > window.innerHeight - 12 ? Math.max(12, aboveTop) : Math.max(12, belowTop);
      detailMentionPopover.style.left = `${left}px`;
      detailMentionPopover.style.top = `${top}px`;
    }

    function createMentionTriggerAtCaret() {
      const selection = window.getSelection();
      if (!selection || !selection.rangeCount || !detailPromptText?.contains(selection.getRangeAt(0).commonAncestorContainer)) return null;
      const range = selection.getRangeAt(0).cloneRange();
      range.collapse(true);
      const trigger = document.createElement("span");
      trigger.className = "detail-mention-trigger";
      trigger.dataset.mentionTrigger = "true";
      trigger.textContent = "@";
      if (range.startContainer?.nodeType === Node.TEXT_NODE && range.startOffset > 0 && range.startContainer.textContent.slice(range.startOffset - 1, range.startOffset) === "@") {
        range.setStart(range.startContainer, range.startOffset - 1);
        range.deleteContents();
      }
      range.insertNode(trigger);
      referenceMentionTriggerNode = trigger;
      const rect = trigger.getBoundingClientRect();
      const nextRange = document.createRange();
      nextRange.setStartAfter(trigger);
      nextRange.collapse(true);
      selection.removeAllRanges();
      selection.addRange(nextRange);
      referenceMentionRange = nextRange.cloneRange();
      return rect;
    }

    function hideReferenceMentionPopover() {
      if (detailMentionPopover) detailMentionPopover.hidden = true;
    }

    function renderReferenceMentionPopover(anchorRect) {
      if (!detailMentionPopover) return;
      const assets = getDetailReferenceMentionAssets();
      detailMentionPopover.innerHTML = assets.map((asset) => {
        const coverStyle = asset.cover ? ` style="background-image:${escapeHtml(asset.cover)}"` : "";
        return `<button class="detail-mention-option" type="button" data-mention-name="${escapeHtml(asset.name)}" data-mention-label="${escapeHtml(asset.label)}" data-mention-kind="${escapeHtml(asset.kind)}" data-mention-cover="${escapeHtml(asset.cover)}"><span class="detail-mention-option-thumb ${referenceKindClass(asset.kind)}"${coverStyle}></span><span>${escapeHtml(asset.label)}</span></button>`;
      }).join("");
      detailMentionPopover.hidden = assets.length === 0;
      if (assets.length) positionReferenceMentionPopover(anchorRect);
    }

    function openReferenceMentionPicker(anchorRect) {
      if (!detailPromptText) return;
      const selection = window.getSelection();
      referenceMentionRange = selection && selection.rangeCount && detailPromptText.contains(selection.getRangeAt(0).commonAncestorContainer)
        ? selection.getRangeAt(0).cloneRange()
        : null;
      detailPromptText.focus();
      referenceInsertMode = "mention";
      // PRD: 输入框输入 @ 或点击左下 @ 时保留输入框内的 @ 字符，并用这个 @ 本身作为定位锚点，让小型选择列表贴在 @ 的下方；选中素材后用原有引用胶囊替换这个 @。
      renderReferenceMentionPopover(anchorRect || referenceMentionTriggerNode?.getBoundingClientRect() || referenceMentionRange?.getBoundingClientRect());
    }

    function insertMentionTriggerAndOpen() {
      if (!detailPromptText) return;
      detailPromptText.focus();
      openReferenceMentionPicker(createMentionTriggerAtCaret());
    }

    detailReferenceAdd?.addEventListener("click", () => {
      hideReferenceMentionPopover();
      referenceInsertMode = "reference";
      activeReferenceSource = "episode";
      activeReferenceCategory = "character";
      referenceAssetOverlay.querySelectorAll("[data-reference-source]").forEach((tab) => tab.classList.toggle("active", tab.dataset.referenceSource === "episode"));
      referenceAssetOverlay.querySelectorAll("[data-library-category]").forEach((tab) => tab.classList.toggle("active", tab.dataset.libraryCategory === "character"));
      renderReferenceLibrary("character", "episode");
      referenceAssetOverlay.hidden = false;
    });

    referenceAssetOverlay?.addEventListener("click", (event) => {
      const sourceTab = event.target.closest("[data-reference-source]");
      if (sourceTab) {
        // PRD 2026-07-08: 本地上传 Tab 直接复用原 input.click()；其余 Tab 只切换当前资产来源。
        if (sourceTab.dataset.referenceSource === "upload") {
          document.getElementById("referenceImageUpload")?.click();
          return;
        }
        referenceAssetOverlay.querySelectorAll("[data-reference-source]").forEach((tab) => tab.classList.toggle("active", tab === sourceTab));
        renderReferenceLibrary(activeReferenceCategory, sourceTab.dataset.referenceSource);
        return;
      }
      const category = event.target.closest("[data-library-category]");
      if (category) {
        referenceAssetOverlay.querySelectorAll("[data-library-category]").forEach((tab) => tab.classList.toggle("active", tab === category));
        renderReferenceLibrary(category.dataset.libraryCategory, activeReferenceSource);
        return;
      }
      const card = event.target.closest("[data-library-name]");
      if (card) {
        // PRD 2026-07-08: 点击新卡片时清掉旧选中态，弹窗始终只能单选一个素材。
        referenceLibraryGrid.querySelectorAll("[data-library-name]").forEach((item) => item.classList.toggle("selected", item === card));
        selectedReferenceLibraryAsset = { name: card.dataset.libraryName, kind: card.dataset.libraryKind, roleName: card.dataset.libraryRole || "" };
        confirmReferenceImport.disabled = false;
        return;
      }
      if (event.target.closest("[data-reference-close], [data-library-cancel]") || event.target === referenceAssetOverlay) referenceAssetOverlay.hidden = true;
    });

    const referenceImageUpload = document.getElementById("referenceImageUpload");
    referenceImageUpload?.addEventListener("change", () => {
      const file = referenceImageUpload.files?.[0];
      if (!file) return;
      const isAudioFile = file.type?.startsWith("audio/") || /\.(mp3|wav|m4a|aac|ogg|flac)$/i.test(file.name || "");
      if (isAudioFile) {
        referenceAudioCount += 1;
        // PRD: 正式版本上传参考音频前需要读取当前片段已添加参考音频的时长总和，并与本次上传音频时长相加；总和超过 15s 时禁止上传，并 toast 提示“上传的所有参考音频的时长总和不能超过 15s”。当前演示版按需求不做真实时长检测，直接允许上传。
        const roleName = getDetailReferenceAudioRoleName();
        // PRD: 参考音频底部标签按“音频 x”编号展示，hover 浮层显示“音色：角色名”，因此上传时保留角色名但不把它作为底部标签。
        commitReferenceAsset({ name: `音色：${roleName}`, kind: "audio", roleName });
      } else {
        commitReferenceAsset({ name: file.name, kind: "role" });
      }
      referenceAssetOverlay.hidden = true;
      referenceImageUpload.value = "";
    });

    confirmReferenceImport?.addEventListener("click", () => {
      if (!selectedReferenceLibraryAsset) return;
      commitReferenceAsset(selectedReferenceLibraryAsset);
      referenceAssetOverlay.hidden = true;
      selectedReferenceLibraryAsset = null;
    });

    detailPromptText?.addEventListener("beforeinput", (event) => {
      if (event.inputType !== "insertText" || event.data !== "@") return;
      referenceMentionTriggerPending = true;
    });

	    detailPromptText?.addEventListener("input", () => {
	      if (!referenceMentionTriggerPending) return;
	      referenceMentionTriggerPending = false;
	      window.requestAnimationFrame(() => openReferenceMentionPicker(createMentionTriggerAtCaret()));
	    });

	    detailPromptText?.addEventListener("click", (event) => {
	      const token = event.target.closest("[data-reference-mention]");
	      if (!token) return;
	      openReferencePreview(getReferencePreviewAssetFromMention(token));
	    });

    detailMentionButton?.addEventListener("pointerdown", (event) => {
      event.preventDefault();
    });

    detailMentionButton?.addEventListener("click", () => {
      insertMentionTriggerAndOpen();
    });

    detailMentionPopover?.addEventListener("click", (event) => {
      const option = event.target.closest("[data-mention-name]");
      if (!option) return;
      insertReferenceMention({
        name: option.dataset.mentionName,
        label: option.dataset.mentionLabel,
        kind: option.dataset.mentionKind,
        cover: option.dataset.mentionCover || ""
      });
    });

    detailPromptText?.addEventListener("keydown", (event) => {
      if (event.key !== "Backspace" && event.key !== "Delete") return;
      const selection = window.getSelection();
      if (!selection || !selection.isCollapsed || !selection.rangeCount) return;
      const range = selection.getRangeAt(0);
      const container = range.startContainer;
      const offset = range.startOffset;
      let target = null;
      if (container.nodeType === Node.TEXT_NODE) {
        if (event.key === "Backspace" && offset > 0 && container.textContent.slice(offset - 1, offset) === "\u00a0") target = container.previousSibling;
        if (event.key === "Backspace" && offset === 0) target = container.previousSibling;
        if (event.key === "Delete" && offset === container.textContent.length) target = container.nextSibling;
      } else {
        const index = event.key === "Backspace" ? offset - 1 : offset;
        target = container.childNodes[index] || null;
      }
      if (target?.nodeType === Node.TEXT_NODE && target.textContent === "\u00a0") target = event.key === "Backspace" ? target.previousSibling : target.nextSibling;
      const token = target?.nodeType === Node.ELEMENT_NODE ? target.closest?.("[data-reference-mention]") : null;
      if (!token) return;
      event.preventDefault();
      const spacer = token.nextSibling?.nodeType === Node.TEXT_NODE && token.nextSibling.textContent === "\u00a0" ? token.nextSibling : null;
      token.remove();
      spacer?.remove();
    });

	    document.addEventListener("keydown", (event) => {
	      if (event.key === "Escape") {
	        hideReferenceMentionPopover();
	        closeReferencePreview();
	      }
	    });

	    referenceAudioPreviewPlay?.addEventListener("click", toggleReferenceAudioPreviewPlayback);

	    [referenceImagePreviewOverlay, referenceAudioPreviewOverlay].forEach((overlay) => {
	      overlay?.addEventListener("click", (event) => {
	        if (event.target === overlay || event.target.closest("[data-reference-preview-close]")) closeReferencePreview();
	      });
	    });

	    const detailVideoSettings = { ratio: "16:9", quality: "1080p", duration: "5s" };

    function setDetailParamPopover(type, open) {
      const controls = {
        model: [detailModelButton, detailModelPopover],
        settings: [detailSettingsButton, detailSettingsPopover]
      };
      Object.entries(controls).forEach(([key, pair]) => {
        const [button, popover] = pair;
        const active = key === type && open;
        if (popover) popover.hidden = !active;
        button?.setAttribute("aria-expanded", String(active));
      });
    }

    detailModelButton?.addEventListener("click", (event) => {
      event.stopPropagation();
      setDetailParamPopover("model", detailModelPopover?.hidden !== false);
    });

    detailSettingsButton?.addEventListener("click", (event) => {
      event.stopPropagation();
      setDetailParamPopover("settings", detailSettingsPopover?.hidden !== false);
    });

    detailModelPopover?.addEventListener("click", (event) => {
      const option = event.target.closest("[data-detail-model]");
      if (!option) return;
      detailModelPopover.querySelectorAll("[data-detail-model]").forEach((item) => item.classList.toggle("selected", item === option));
      if (detailModelLabel) detailModelLabel.textContent = option.dataset.detailModel;
      setDetailParamPopover("model", false);
    });

    detailSettingsPopover?.addEventListener("click", (event) => {
      const option = event.target.closest("[data-detail-setting]");
      if (!option) return;
      const key = option.dataset.detailSetting;
      detailVideoSettings[key] = option.dataset.value;
      detailSettingsPopover.querySelectorAll(`[data-detail-setting="${key}"]`).forEach((item) => item.classList.toggle("selected", item === option));
      if (detailSettingsLabel) detailSettingsLabel.textContent = `${detailVideoSettings.quality} · ${detailVideoSettings.ratio}`;
    });

    detailDurationButton?.addEventListener("click", (event) => {
      event.stopPropagation();
      setDetailDurationPopover(detailDurationPopover?.hidden !== false);
    });

    const detailDurationRange = document.getElementById("detailDurationRange");
    const detailDurationInput = document.getElementById("detailDurationInput");
    const applyDetailDurationValue = (value) => {
      const seconds = Math.min(15, Math.max(4, parseInt(value, 10) || 4));
      applyShotDuration(getActiveShotCard(), `${seconds}s`);
    };
    // 2026-08-06 改动逻辑：拖动短剧时长滑杆即时更新当前片段；数字输入在范围内即时更新，失焦或回车时自动限制到 4-15 秒。
    detailDurationRange?.addEventListener("input", () => applyDetailDurationValue(detailDurationRange.value));
    detailDurationInput?.addEventListener("input", () => {
      const seconds = parseInt(detailDurationInput.value, 10);
      if (Number.isFinite(seconds) && seconds >= 4 && seconds <= 15) applyDetailDurationValue(seconds);
    });
    detailDurationInput?.addEventListener("change", () => applyDetailDurationValue(detailDurationInput.value));
    detailDurationInput?.addEventListener("keydown", (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      applyDetailDurationValue(detailDurationInput.value);
      detailDurationInput.blur();
    });

    document.addEventListener("click", (event) => {
      if (event.target.closest("#detailModelPopover, #detailSettingsPopover, #detailModelButton, #detailSettingsButton")) return;
      setDetailParamPopover("model", false);
      if (event.target.closest("#detailDurationPopover, #detailDurationButton")) return;
      setDetailDurationPopover(false);
      if (event.target.closest("#detailMentionPopover, #detailMentionButton, #detailPromptText")) return;
      hideReferenceMentionPopover();
    });

    detailGenerateButton?.addEventListener("click", generateDetailVideoPreview);

    detailFullscreenButton?.addEventListener("click", openDetailPreviewFullscreen);

    const episodeActionNoticeModal = document.getElementById("episodeActionNoticeModal");
    const closeEpisodeActionNotice = () => {
      if (episodeActionNoticeModal) episodeActionNoticeModal.hidden = true;
    };
    episodeActionNoticeModal?.querySelector("[data-episode-action-notice-confirm]")?.addEventListener("click", closeEpisodeActionNotice);

    document.querySelectorAll("[data-episode-action]").forEach((button) => {
      button.addEventListener("click", () => {
        const episodeCard = button.closest("[data-episode-card]");
        const title = episodeCard?.dataset.episodeTitle || currentEpisodeVideoTitle;
        const state = getEpisodeVideoState(title);
        // 改动逻辑：列表按钮只使用该集最近一次检测结果，不再读取当前详情页 DOM 或在后台轮询所有片段。
        if (!state.clipsGenerated) {
          // 改动逻辑：未完成集的播放和下载都使用明确提醒弹窗，用户确认后只关闭弹窗，不触发生成或合成。
          if (episodeActionNoticeModal) episodeActionNoticeModal.hidden = false;
          return;
        }
        if (!state.merged) {
          openEpisodeMergeConfirmModal(title);
          return;
        }
        if (button.dataset.episodeAction === "watch") {
          // PRD: 观看入口应打开最新一次后端合成完成的整集视频；原型用当前分集卡片封面进入全屏演示。
          const fullscreenTarget = episodeCard?.querySelector(".episode-cover") || episodeCard;
          fullscreenTarget?.requestFullscreen?.();
          fullscreenTarget?.webkitRequestFullscreen?.();
          return;
        }
        // PRD: 下载入口应下载最新一次后端合成完成的视频文件；原型仅用 toast 表达下载动作已触发。
        showTitleToast("已开始下载最新合成视频");
      });
    });

    detailPlayBtn?.addEventListener("click", () => {
      if (!detailVideo) return;
      if (detailVideo.paused) {
        detailSegmentEnding = false;
        playDetailVideo();
      } else {
        stopDetailVideo();
      }
    });

    detailVideo?.addEventListener("timeupdate", () => {
      const activeCard = document.querySelector(".shot-card.active");
      const plannedDuration = parseShotSeconds(activeCard?.dataset.duration);
      const current = Math.min(plannedDuration, detailVideo.currentTime || 0);
      const percent = Math.min(100, (current / plannedDuration) * 100);
      detailProgress?.style.setProperty("--progress", `${percent}%`);
      if (detailVideoTime) {
        detailVideoTime.textContent = `00:${String(Math.floor(current)).padStart(2, "0")} / 00:${String(plannedDuration).padStart(2, "0")}`;
      }
      if (!detailVideo.paused && current >= plannedDuration) finishCurrentShot();
    });

    detailVideo?.addEventListener("ended", () => {
      detailProgress?.style.setProperty("--progress", "100%");
      finishCurrentShot();
    });

    canvasOpeners.forEach((opener) => {
      opener.addEventListener("click", () => openCanvasView("drama"));
    });

    assetPanelTabs.forEach((tab) => {
      tab.addEventListener("click", () => {
        // PRD: 图二资产分类里“物品”数量为 0 时没有 data-asset-panel-target 且处于 disabled；点击或脚本触发都不允许切换到物品空面板。
        if (tab.disabled || !tab.dataset.assetPanelTarget) return;
        const target = tab.dataset.assetPanelTarget;
        assetPanelTabs.forEach((item) => {
          const active = item === tab;
          item.classList.toggle("active", active);
          item.setAttribute("aria-pressed", String(active));
        });
        assetPanels.forEach((panel) => {
          panel.hidden = panel.dataset.assetPanel !== target;
        });
      });
    });

    canvasReturn?.addEventListener("click", () => {
      canvasWorkbench?.classList.remove("from-drama");
      setActiveNav("canvas");
      showView("asset-library");
    });

    window.addEventListener("message", (event) => {
      if (event.source !== canvasFrame?.contentWindow) return;
      if (event.data?.type !== "vina-canvas-return-home") return;
      canvasWorkbench?.classList.remove("from-drama");
      setActiveNav("canvas");
      showView("canvas");
    });

    scriptBackButtons.forEach((button) => {
      button.addEventListener("click", (event) => {
        if (event.target.closest("[data-script-project-title], .script-title-input")) return;
        const target = button.dataset.viewTargetInline;
        if (target === "drama") {
          setActiveNav("canvas");
          setHomeComposerTab("drama");
          showView("canvas");
          return;
        }
        showView(target);
      });
    });

    scriptProjectTitleNodes.forEach((titleNode) => {
      titleNode.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        if (titleNode.hidden || titleNode.parentElement?.querySelector(".script-title-input")) return;
        startScriptTitleEdit(titleNode);
      });
    });

    const updateDramaGenerateState = () => {
      const hasText = Boolean(dramaScriptText?.value.trim());
      const hasFile = Boolean(scriptFileInput?.files?.length);
      dramaGenerateButton?.classList.toggle("is-ready", hasText || hasFile);
    };

    const truncateScriptFileName = (name) => {
      if (!name || name.length <= 8) return name || "上传剧本";
      return `${name.slice(0, 8)}...`;
    };

    const resetScriptUpload = () => {
      if (scriptFileInput) scriptFileInput.value = "";
      scriptUploadButton?.classList.remove("has-file");
      if (scriptFileName) {
        scriptFileName.textContent = "上传剧本";
        scriptFileName.removeAttribute("title");
      }
      updateDramaGenerateState();
    };

    scriptUploadButton?.addEventListener("click", (event) => {
      if (event.target.closest("[data-script-file-remove]")) return;
      scriptFileInput?.click();
    });

    scriptFileRemove?.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      resetScriptUpload();
    });

    scriptFileRemove?.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      event.preventDefault();
      event.stopPropagation();
      resetScriptUpload();
    });

    scriptFileInput?.addEventListener("change", () => {
      const file = scriptFileInput.files?.[0];
      if (!file) {
        resetScriptUpload();
        return;
      }

      scriptUploadButton?.classList.add("has-file");
      if (scriptFileName) {
        scriptFileName.textContent = truncateScriptFileName(file.name);
        scriptFileName.title = file.name;
      }
      updateDramaGenerateState();
    });

	    dramaScriptText?.addEventListener("input", updateDramaGenerateState);
	    updateDramaGenerateState();

	    // 初始化时同步参考编号后重绘预置提示词，确保默认 @图片/@音频 文本立即显示为可点击的素材标签。
	    syncDetailReferenceLabels();
	    setDetailPromptContent(detailPromptText?.textContent || "");

	    const batchGenerateModal = document.getElementById("batchGenerateModal");
    const batchGenerateMessage = document.getElementById("batchGenerateMessage");
    const batchGenerateDescription = document.getElementById("batchGenerateDescription");
    let pendingBatchGenerateType = "";

    const closeBatchGenerateModal = () => {
      if (batchGenerateModal) batchGenerateModal.hidden = true;
      if (batchGenerateDescription) {
        batchGenerateDescription.hidden = true;
        batchGenerateDescription.textContent = "";
      }
      pendingBatchGenerateType = "";
    };

    const openBatchGenerateModal = (type) => {
      pendingBatchGenerateType = type;
      if (batchGenerateMessage) {
        // 2026-08-18 改动逻辑：重新规划脚本使用更明确的确认标题，其他批量生成操作继续沿用原文案。
        batchGenerateMessage.textContent = type === "characters"
          ? "确定要一键生成全部图片吗？"
          : type === "episode-script-replan"
            ? "确认重新规划本集脚本？"
            : "确定要一键生成全部视频片段吗？";
      }
      if (batchGenerateDescription) {
        const showDescription = type === "episode-script-replan";
        batchGenerateDescription.hidden = !showDescription;
        batchGenerateDescription.textContent = showDescription
          ? "重新规划后，本集已生成的视频将失效，且无法恢复。"
          : "";
      }
      if (batchGenerateModal) batchGenerateModal.hidden = false;
    };

    // PRD placeholder only: this disabled control previews a future batch flow for generating missing asset images and auto-binding public-library voices to character nodes.
    document.getElementById("detailGenerateAll")?.addEventListener("click", () => openBatchGenerateModal("clips"));
    // 2026-08-18 改动逻辑：重新规划脚本先进入风险确认，只有用户确认后才废弃旧视频并返回分集列表。
    detailRegenerateScript?.addEventListener("click", () => openBatchGenerateModal("episode-script-replan"));
    batchGenerateModal?.querySelector("[data-batch-generate-cancel]")?.addEventListener("click", closeBatchGenerateModal);
    batchGenerateModal?.querySelector("[data-batch-generate-confirm]")?.addEventListener("click", () => {
      const confirmedType = pendingBatchGenerateType;
      closeBatchGenerateModal();
      document.dispatchEvent(new CustomEvent("vina-batch-generate-confirmed", { detail: { type: confirmedType } }));
    });

    document.addEventListener("vina-batch-generate-confirmed", (event) => {
      const confirmedType = event.detail?.type;
      if (confirmedType === "clips") {
        startShotGenerationPrototype(refreshShotCards());
        return;
      }
      if (confirmedType === "episode-merge") {
        startEpisodeMergePrototype(currentEpisodeVideoTitle);
        return;
      }
      if (confirmedType === "episode-script-replan") {
        startEpisodeScriptReplanPrototype(currentEpisodeVideoTitle);
      }
    });

    document.querySelectorAll(".ai-script-box textarea").forEach((textarea) => {
      textarea.addEventListener("keydown", (event) => {
        if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
          event.preventDefault();
          showView("script-studio");
        }
      });
    });

    (() => {
      const injectedOverlaySelector = [
        "volc-translate",
        "#agent",
        "#ai-assist-root",
        "#ai-assist-root-new",
        "#ai-assist-root-bangs",
        "#ai-assist-bangs",
        "#shadow-root-ai-assist",
        "#immersive-translate-browser-popup",
        "#immersive-translate-popup-overlay",
        ".immersive-translate-popup-overlay",
        ".immersive-translate-popup-wrapper",
        ".imt-float-ball",
        ".imt-fb-side",
        ".imt-fb-container",
        ".qa-sdk-wrapper",
        "#youAsk_side",
        "[id^='youAsk']",
        "[class*='youAsk']",
        "[id*='ai-assist']",
        "[class*='ai-assist']",
        "[id*='immersive-translate']",
        "[class*='immersive-translate']"
      ].join(",");

      const removeOpenShadowHosts = (root) => {
        if (!root || root.nodeType !== 1) return;
        if (root.shadowRoot) {
          root.remove();
          return;
        }
        root.querySelectorAll("*").forEach((node) => {
          if (node.shadowRoot) node.remove();
        });
      };

      const cleanupRuntimeOverlayHosts = () => {
        document.querySelectorAll(injectedOverlaySelector).forEach((node) => node.remove());
        document.querySelectorAll("template[shadowrootmode], template[shadowroot]").forEach((template) => {
          const host = template.parentElement;
          // PRD: VinaAgent 主页面不使用 Shadow DOM；扩展即使把未知宿主插进 .app 内也必须移除，防止原先按产品根豁免后漏掉右半屏蒙版。
          if (host) host.remove();
        });
        // PRD: HTML 标准结构只保留 head/body；扩展追加到 body 之外的同级遮罩节点直接删除，避免仅清理 body 时漏掉右半屏覆盖层。
        Array.from(document.documentElement.children).forEach((node) => {
          if (node === document.head || node === document.body) return;
          node.remove();
        });
      };

      cleanupRuntimeOverlayHosts();
      removeOpenShadowHosts(document.documentElement);
      new MutationObserver((records) => {
        cleanupRuntimeOverlayHosts();
        // PRD: 主界面有大量业务 DOM 更新；运行期只检查新增分支，既拦截扩展 Shadow DOM，又不让遮罩清理拖慢画布交互。
        records.forEach((record) => {
          record.addedNodes.forEach(removeOpenShadowHosts);
        });
      }).observe(document.documentElement, {
        childList: true,
        subtree: true
      });
    })();
  
